const queries = [
  'Canadian universities application fee waiver for graduate (masters and PhD) programs, international applicants, 2027 intake',
  'Canadian university graduate application fee waiver request for applicants from Africa, Nigeria or developing countries',
  'graduate application fee waiver at University of Toronto, UBC, McGill, Waterloo, Alberta, Calgary, Dalhousie, Queens, Western, McMaster, Ottawa, Simon Fraser',
  'scholarships for international graduate students (masters and PhD) at Canadian universities, 2027 intake, deadlines',
  'fully funded masters and PhD programs in Canada for international students, assistantships and guaranteed funding packages, 2026-2027',
  'graduate scholarships and fellowships in Canada open to students from Africa and Nigeria, 2026-2027'
];
return queries.map(q => ({ json: { query: q } }));

const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || {};
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const attr = s => esc(s).replace(/"/g, '&quot;');
const order = { 'application fee waiver': 0, 'scholarship': 1, 'funding': 2 };
const rank = t => (order[t.toLowerCase()] === undefined ? 9 : order[t.toLowerCase()]);
const found = [];
const runKeys = {};
for (const item of $input.all()) {
  const content = item.json && (item.json.text || item.json.output);
  if (!content) continue;
  let arr = [];
  try {
    const m = String(content).match(/\[[\s\S]*\]/);
    arr = JSON.parse(m ? m[0] : content);
  } catch (e) { continue; }
  if (!Array.isArray(arr)) continue;
  for (const r of arr) {
    if (!r || !r.url || !/^https?:\/\//i.test(r.url)) continue;
    const type = String(r.type || 'Other').trim();
    const key = r.university ? 'u:' + String(r.university).trim().toLowerCase() + '|' + type.toLowerCase() + '|' + String(r.title || '').trim().toLowerCase() : 'l:' + String(r.url).split('#')[0].toLowerCase();
    if (sd.seen[key] || runKeys[key]) continue;
    runKeys[key] = true;
    found.push({ key: key, type: type, r: r });
  }
}
if (!found.length) return [];
found.sort((a, b) => rank(a.type) - rank(b.type));
for (const f of found) sd.seen[f.key] = Date.now();
const header = '<b>Canada grad school fee waivers, scholarships and funding: ' + found.length + ' new</b>\n\n';
const blocks = found.map(f => {
  const r = f.r;
  let b = '<b>' + esc(r.university) + '</b>';
  if (r.province) b += ' (' + esc(r.province) + ')';
  if (r.level) b += ' - ' + esc(r.level);
  b += '\n[' + esc(f.type) + ']';
  if (r.title) b += ' ' + esc(r.title);
  b += '\n';
  const d = r.details || r.waiver_details;
  if (d) b += 'Details: ' + esc(d) + '\n';
  if (r.eligibility) b += 'Who: ' + esc(r.eligibility) + '\n';
  if (r.deadline) b += 'Deadline: ' + esc(r.deadline) + '\n';
  b += '<a href="' + attr(r.url) + '">Official page</a>\n';
  return b;
});
const footer = '\nAlways confirm terms, amounts and deadlines on the official page before applying.';
const msgs = [];
let cur = header;
for (const b of blocks) {
  if ((cur + b).length > 3500) { msgs.push(cur); cur = ''; }
  cur += b + '\n';
}
cur += footer;
msgs.push(cur);
return msgs.map(m => ({ json: { message: m } }));
